package com.flipcash.services.models.chat

import kotlinx.serialization.Serializable

/**
 * A preview of a link in the text that carries it (`messaging.v1.LinkPreview`), generated by the
 * sending device. These are the sender's claims about the page: show [url]'s host with it.
 *
 * [image] is one item with an ORIGINAL rendition, as for chat media.
 */
@Serializable
data class LinkPreview(
    val url: String,
    val title: String,
    val description: String = "",
    val image: MediaItem? = null,
)
